    'ui_off_by_default_provider_passwords_are': '\u0645\u0639\u0637\u0644 \u0627\u0641\u062a\u0631\u0627\u0636\u064a\u064b\u0627\u060c \u0644\u0627 \u062a\u062a\u0645 \u0645\u0632\u0627\u0645\u0646\u0629 \u0643\u0644\u0645\u0627\u062a \u0645\u0631\u0648\u0631 \u0645\u0632\u0648\u062f \u0627\u0644\u062e\u062f\u0645\u0629 \u0623\u0628\u062f\u064b\u0627. \u0634\u063a\u0651\u0644 \u0647\u0630\u0627 \u0644\u0645\u0632\u0627\u0645\u0646\u062a\u0647\u0627 \u0645\u0634\u0641\u0631\u0629 \u0645\u0646 \u0637\u0631\u0641 \u0625\u0644\u0649 \u0637\u0631\u0641 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0639\u0628\u0627\u0631\u0629 \u0645\u0631\u0648\u0631 \u062a\u0639\u0631\u0641\u0647\u0627 \u0623\u0646\u062a \u0641\u0642\u0637. \u0644\u0627 \u064a\u062a\u0645 \u0625\u0631\u0633\u0627\u0644 \u0639\u0628\u0627\u0631\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0625\u0644\u0649 \u0627\u0644\u062e\u0627\u062f\u0645 \u0623\u0628\u062f\u064b\u0627 \u0648\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u0631\u062c\u0627\u0639\u0647\u0627 \u0641\u064a \u062d\u0627\u0644\u0629 \u0641\u0642\u062f\u0627\u0646\u0647\u0627.',
    'ui_pair_your_tv_to_load_your': 'اقرن جهازك لتحميل مصادرك. استخدم هاتفك لمسح الرمز أو أدخل رمز الاقتران على موقعنا.',
